        "body_type": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": "plain",
          "description": "Body format - \"plain\" or \"html\" (default: \"plain\").",
          "title": "Body Type"
        },
        "signature": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Email signature to append.",
          "title": "Signature"
